/**
 * FAQ / generic accordion. Markup is generated by renderers using
 * accItem(); this module wires open/close behaviour.
 */
import { icon } from '../utils/dom.js'

export function accItem(q, a) {
  return `
  <div class="acc-item reveal">
    <button class="acc-btn" type="button">
      <span class="text-start font-bold text-ink text-[0.98rem] leading-7">${q}</span>
      ${icon('plus', 'acc-icon h-5 w-5')}
    </button>
    <div class="acc-body" data-open="false">
      <div><p class="acc-content">${a}</p></div>
    </div>
  </div>`
}

export function mountAccordions(root = document) {
  root.querySelectorAll('.acc-item').forEach((item) => {
    const btn = item.querySelector('.acc-btn')
    const body = item.querySelector('.acc-body')
    btn.addEventListener('click', () => {
      const open = body.dataset.open === 'true'
      body.dataset.open = open ? 'false' : 'true'
      item.classList.toggle('open', !open)
      btn.setAttribute('aria-expanded', String(!open))
    })
  })
}
